CREATE TABLE IF NOT EXISTS autores (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre VARCHAR(100) NOT NULL, nacionalidad VARCHAR(50));
CREATE TABLE IF NOT EXISTS libros (id INTEGER PRIMARY KEY AUTOINCREMENT, isbn INTEGER NOT NULL UNIQUE, titulo VARCHAR(150) NOT NULL, precio DECIMAL(6,2), disponible BOOLEAN DETAULT true, autor_id INTEGER, CONSTRAINT fk_autores_libros
                        FOREIGN KEY (autor_id) REFERENCES autores(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS socios (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre VARCHAR(100) NOT NULL, email VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS prestamos (id INTEGER PRIMARY KEY AUTOINCREMENT, id_socio INTEGER NOT NULL, id_libro INTEGER NOT NULL, fecha_prestamo DATE NOT NULL, fecha_devolucion DATE, CONSTRAINT fk_socio_prestamo FOREIGN KEY (id_socio) REFERENCES socios(id) ON DELETE CASCADE,
                        CONSTRAINT fk_libor_prestamo FOREIGN KEY (id_libro) REFERENCES libros(id) ON DELETE CASCADE);